// stage content:
(lib.anuncio2 = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.actionFrames = [0];
	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.miBoton.addEventListener("click", function() {
		    window.open("https://www.qecalix.com/search/label/MECOMIC", "_blank");
		});
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Capa_6
	this.shape = new cjs.Shape();
	this.shape.graphics.f("#666666").s().p("");
	this.shape.setTransform(439.225,518.2693);

	this.timeline.addTween(cjs.Tween.get(this.shape).wait(1));

	// lineamota
	this.instance = new lib.CachedBmp_1();
	this.instance.setTransform(177.8,544.15,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get(this.instance).wait(1));

	// boton
	this.miBoton = new lib.botoncomic();
	this.miBoton.name = "miBoton";
	this.miBoton.setTransform(152.6,575.4,1,1,0,0,0,59.4,109.6);
	new cjs.ButtonHelper(this.miBoton, 0, 1, 2);

	this.timeline.addTween(cjs.Tween.get(this.miBoton).wait(1));

	// bloque
	this.instance_1 = new lib.CachedBmp_3();
	this.instance_1.setTransform(417.5,359.95,0.5,0.5);

	this.instance_2 = new lib.CachedBmp_2();
	this.instance_2.setTransform(27,-61.7,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_2},{t:this.instance_1}]}).wait(1));

	// fondo
	this.instance_3 = new lib.CachedBmp_4();
	this.instance_3.setTransform(-81,-95.65,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get(this.instance_3).wait(1));

	// boceto
	this.instance_4 = new lib.CachedBmp_5();
	this.instance_4.setTransform(-20.35,-22.65,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get(this.instance_4).wait(1));

	this._renderFirstFrame();

}).prototype = p = new lib.AnMovieClip();
